-- Query: qryFinalSecondAnalysis
-- DAO query type: 64

INSERT INTO tblSecondAnalysis2 ( [Month], ProjName, WorkOrdr, WoLogDate, DPDueDate, DPDateComp, ShippingDueDate, ShipDate, LeadTimeToProcessWO, SmplPerb, SmplPerE, ReportDueDate, LastSampRecDate, SampReleaseDate, Category, Late, [#ofSample], AfterDateSampled, [Notes-SampleLateArrival], [#ofDatesBetweenSamplePerE_LastSampRecDate], SmplLastTested, TTA_UponReciept, [Notes-Testing] )
SELECT tblSecondAnalysis.Month, tblSecondAnalysis.ProjName, tblSecondAnalysis.WorkOrdr, tblSecondAnalysis.LgDate AS WoLogDate, tblSecondAnalysis.DPDueDate, tblSecondAnalysis.DPDateComp, tblSecondAnalysis.ShippingDueDate, tblSecondAnalysis.ShipDate, CDate(Nz([SmplPerB]))-CDate(Nz([lgdate])) AS LeadTimeToProcessWO, tblSecondAnalysis.SmplPerb, tblSecondAnalysis.SmplPerE, [SmplPerE]+[ReportDate] AS ReportDueDate, qry_KPI_1_RecVDate_Auto.LastSampRecDate, tbl_ReleaseDateByWO.SampReleaseDate, tblProjects.Category, IIf(Not IsNull([SampReleaseDate]),IIf(DateValue([SmplPerE]+[ReportDate])-DateValue([SampReleaseDate])<0,"Late",""),IIf(([SmplPerE]+[ReportDate])<Date(),"Late","")) AS Late, Count(tblSecondAnalysis.SampleId) AS [#ofSample], IIf([dteSampled]<>"","After","") AS AfterDateSampled, "" AS [Notes-SampleLateArrival], CDate(Nz([LastSampRecDate]))-CDate(Nz([Smplpere])) AS [#ofDatesBetweenSamplePerE_LastSampRecDate], tbl_LastTested_SmplUPD.SmplUpdD AS SmplLastTested, CDate(Nz([SampReleaseDate]))-CDate(Nz([LastSampRecDate])) AS TTA_UponReciept, "" AS [Notes-Testing]
FROM (((tblSecondAnalysis INNER JOIN qry_KPI_1_RecVDate_Auto ON (tblSecondAnalysis.WorkOrdr = qry_KPI_1_RecVDate_Auto.WorkOrdr) AND (tblSecondAnalysis.ProjName = qry_KPI_1_RecVDate_Auto.ProjName)) INNER JOIN tbl_ReleaseDateByWO ON (tblSecondAnalysis.WorkOrdr = tbl_ReleaseDateByWO.WorkOrdr) AND (tblSecondAnalysis.ProjName = tbl_ReleaseDateByWO.ProjName)) LEFT JOIN tbl_LastTested_SmplUPD ON (tblSecondAnalysis.WorkOrdr = tbl_LastTested_SmplUPD.WorkOrdr) AND (tblSecondAnalysis.ProjName = tbl_LastTested_SmplUPD.ProjName)) INNER JOIN tblProjects ON tblSecondAnalysis.ProjName = tblProjects.Project
GROUP BY tblSecondAnalysis.Month, tblSecondAnalysis.ProjName, tblSecondAnalysis.WorkOrdr, tblSecondAnalysis.LgDate, tblSecondAnalysis.DPDueDate, tblSecondAnalysis.DPDateComp, tblSecondAnalysis.ShippingDueDate, tblSecondAnalysis.ShipDate, CDate(Nz([SmplPerB]))-CDate(Nz([lgdate])), tblSecondAnalysis.SmplPerb, tblSecondAnalysis.SmplPerE, [SmplPerE]+[ReportDate], qry_KPI_1_RecVDate_Auto.LastSampRecDate, tbl_ReleaseDateByWO.SampReleaseDate, tblProjects.Category, IIf(Not IsNull([SampReleaseDate]),IIf(DateValue([SmplPerE]+[ReportDate])-DateValue([SampReleaseDate])<0,"Late",""),IIf(([SmplPerE]+[ReportDate])<Date(),"Late","")), IIf([dteSampled]<>"","After",""), CDate(Nz([LastSampRecDate]))-CDate(Nz([Smplpere])), tbl_LastTested_SmplUPD.SmplUpdD, CDate(Nz([SampReleaseDate]))-CDate(Nz([LastSampRecDate])), "", ""
ORDER BY tblSecondAnalysis.Month DESC , tblSecondAnalysis.ProjName, tblSecondAnalysis.WorkOrdr, tblSecondAnalysis.SmplPerE;


